/**
 * Brand Lottie animations (src/ui/lottie/*.json, generated by tools/gen-lottie.mjs).
 * The player is lottie-web's light SVG build (no expressions, so no eval under the CSP) and loads on demand
 * with the animation data, about 47KB gzipped once for the whole app. Until it arrives the static logomark holds the
 * place, so a loading state is never blank. Reduced motion shows the finished frame and never loops.
 */
import { useEffect, useRef, useState } from 'react';
import { LogoMark } from '../brand';

export type LottieName = 'loader' | 'success' | 'envelope';

const DATA: Record<LottieName, () => Promise<{ default: unknown }>> = {
  loader: () => import('../lottie/loader.json'),
  success: () => import('../lottie/success.json'),
  envelope: () => import('../lottie/envelope.json'),
};
/** the frame shown under reduced motion: the drawn mark, the closed seal, the card risen */
const REST: Record<LottieName, number> = { loader: 46, success: 71, envelope: 96 };

type Player = { loadAnimation: (o: object) => { destroy(): void; goToAndStop(f: number, isFrame: boolean): void; addEventListener(e: string, fn: () => void): void } };
let playerP: Promise<Player> | null = null;
const player = () => (playerP ??= import('lottie-web/build/player/lottie_light').then((m) => (m.default ?? m) as unknown as Player));

const reducedMotion = () => typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches;

export function Lottie({ name, size = 72, loop = name !== 'success', label, className = '', onDone }: {
  name: LottieName; size?: number; loop?: boolean; label?: string; className?: string; onDone?: () => void;
}) {
  const host = useRef<HTMLSpanElement>(null);
  const [ready, setReady] = useState(false);
  const done = useRef(onDone);
  done.current = onDone;
  useEffect(() => {
    let alive = true;
    let anim: ReturnType<Player['loadAnimation']> | null = null;
    Promise.all([player(), DATA[name]()]).then(([lottie, data]) => {
      if (!alive || !host.current) return;
      const still = reducedMotion();
      anim = lottie.loadAnimation({ container: host.current, renderer: 'svg', loop: still ? false : loop, autoplay: !still, animationData: data.default,
        rendererSettings: { preserveAspectRatio: 'xMidYMid meet', progressiveLoad: false } });
      if (still) { anim.goToAndStop(REST[name], true); done.current?.(); }
      else anim.addEventListener('complete', () => done.current?.());
      setReady(true);
    }).catch(() => { if (alive) done.current?.(); });
    return () => { alive = false; anim?.destroy(); };
  }, [name, loop]);
  return (
    <span className={`lottie lottie-${name}${ready ? ' is-ready' : ''} ${className}`} style={{ width: size, height: size }}
      role={label ? 'img' : undefined} aria-label={label} aria-hidden={label ? undefined : true}>
      {!ready && name === 'loader' && <LogoMark size={size * 0.62} className="lottie-ph" />}
      <span ref={host} className="lottie-host" />
    </span>
  );
}

/** a centred loading state for a page or panel: the logomark drawing itself and one quiet line */
export function PageLoader({ label = 'جارٍ التحميل', name = 'loader', size = 72 }: { label?: string; name?: LottieName; size?: number }) {
  return (
    <div className="page-loader" role="status" aria-live="polite">
      <Lottie name={name} size={size} />
      <p className="page-loader-text">{label}</p>
    </div>
  );
}
